namespace Paramore.Brighter.Kafka.Tests.MessagingGateway.Classic.Proactor;

/// <summary>
/// An unacceptable message goes to the invalid-message channel and not the dead-letter queue; the
/// absence is checked with one bounded receive, since a poll could only wait out its ceiling.
/// </summary>
[Trait("Category", "Kafka")]
[Collection("Kafka")]
public class WhenRejectingMessageWithUnacceptableReasonShouldSendToInvalidChannelAsync : IAsyncLifetime
{
    private readonly IAmAMessageGatewayProactorProvider _messageGatewayProvider;
    private readonly IAmAMessageBuilder _messageBuilder;

    private List<Message> _sentMessages = [];

    private Paramore.Brighter.MessagingGateway.Kafka.KafkaSubscription? _subscription;
    private Paramore.Brighter.MessagingGateway.Kafka.KafkaPublication? _publication;

    private IAmAMessageProducerAsync? _producer;
    private IAmAChannelAsync? _channel;

    public WhenRejectingMessageWithUnacceptableReasonShouldSendToInvalidChannelAsync()
    {
        _messageGatewayProvider = new Paramore.Brighter.Kafka.Tests.MessagingGateway.KafkaClassicMessageGatewayProvider();
        _messageBuilder = new DefaultMessageBuilder();
    }

    public Task InitializeAsync()
    {
        return Task.CompletedTask;
    }

    public async Task DisposeAsync()
    {
        await _messageGatewayProvider.CleanUpAsync(_producer, _channel, _sentMessages);
    }

    [Fact]
    public async Task When_rejecting_message_with_unacceptable_reason_should_send_to_invalid_channel_async()
    {
        // Arrange
        _publication = _messageGatewayProvider.CreatePublication(_messageGatewayProvider.GetOrCreateRoutingKey());
        _subscription = _messageGatewayProvider.CreateSubscription(_publication.Topic!,
            _messageGatewayProvider.GetOrCreateChannelName(),
            OnMissingChannel.Create,
            deadLetterRoutingKey: new RoutingKey($"{_publication.Topic!}.DLQ"),
            invalidMessageRoutingKey: new RoutingKey($"{_publication.Topic!}.Invalid"));

        _producer = await _messageGatewayProvider.CreateProducerAsync(_publication);
        _channel = await _messageGatewayProvider.CreateChannelAsync(_subscription);

        var message = _messageBuilder.SetTopic(_publication.Topic!).Build();
        _sentMessages.Add(message);

        await _producer.SendAsync(message);

        // Act
        var received = await _channel.ReceiveAsync(TimeSpan.FromMilliseconds(15000));
        Assert.NotEqual(MessageType.MT_NONE, received.Header.MessageType);

        var rejected = await _channel.RejectAsync(received, new MessageRejectionReason(RejectionReason.Unacceptable, "Test unacceptable message"));

        // Assert
        Assert.True(rejected, "RejectAsync should return true when the message was routed");

        // Assert
        var invalidMessage = new Message();
        var stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < TimeSpan.FromSeconds(60))
        {
            invalidMessage = await _messageGatewayProvider.GetMessageFromInvalidChannelAsync(_subscription);
            if (invalidMessage.Header.MessageType != MessageType.MT_NONE)
            {
                break;
            }
            await Task.Delay(500);
        }

        Assert.NotEqual(MessageType.MT_NONE, invalidMessage.Header.MessageType);
        Assert.Equal(message.Body.Value, invalidMessage.Body.Value);

        var keys = _messageGatewayProvider.RejectionMetadataKeys;
        if (keys.StampsRejectionMetadata)
        {
            Assert.True(invalidMessage.Header.Bag.ContainsKey(keys.OriginalTopic));
            Assert.Equal(_publication.Topic!.Value, invalidMessage.Header.Bag[keys.OriginalTopic].ToString());
            Assert.True(invalidMessage.Header.Bag.ContainsKey(keys.RejectionReason));
            Assert.Equal(RejectionReason.Unacceptable.ToString(), invalidMessage.Header.Bag[keys.RejectionReason].ToString());
        }

        // Assert
        var dlqMessage = await _messageGatewayProvider.GetMessageFromDeadLetterQueueAsync(_subscription);
        Assert.Equal(MessageType.MT_NONE, dlqMessage.Header.MessageType);
    }
